#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(SummarizedExperiment); library(survival); library(survminer); library(ggplot2); library(dplyr); library(tidyr); library(readr); library(tibble); library(broom)})
options(stringsAsFactors = FALSE)
root <- normalizePath('.', mustWork=TRUE)
infile <- file.path(root, 'data/raw/TCGA_PAAD_RNAseq.rds')
outdir <- file.path(root, 'results/tcga_paad_external'); dir.create(outdir, recursive=TRUE, showWarnings=FALSE)
figdir <- file.path(outdir, 'figures'); dir.create(figdir, recursive=TRUE, showWarnings=FALSE)
zmean <- function(expr, genes) { genes <- intersect(unique(genes), rownames(expr)); if (!length(genes)) return(rep(NA_real_, ncol(expr))); zz <- t(apply(expr[genes,,drop=FALSE],1,function(x) as.numeric(scale(x)))); if (length(genes)==1) zz <- matrix(zz,nrow=1); colMeans(zz,na.rm=TRUE) }
safe_cor <- function(x,y,method='spearman') { ok <- is.finite(x)&is.finite(y); if (sum(ok)<5 || sd(x[ok])==0 || sd(y[ok])==0) return(c(rho=NA,p=NA,n=sum(ok))); ct <- suppressWarnings(cor.test(x[ok],y[ok],method=method,exact=FALSE)); c(rho=unname(ct$estimate),p=ct$p.value,n=sum(ok)) }
sig <- list(
 immune_infiltration=c('PTPRC','HLA-DRA','HLA-DRB1','CD3D','CD3E','CD8A','MS4A1','NKG7','LST1','TYROBP','FCER1G','CD68'),
 t_cell=c('CD3D','CD3E','CD3G','TRBC1','TRBC2','CD4','CD8A','CD8B','IL7R','LTB'),
 cytotoxic=c('NKG7','GNLY','GZMB','GZMH','PRF1','GZMK','CTSW'),
 b_cell=c('MS4A1','CD79A','CD37','CD74','HLA-DRA','CD79B','CD19'),
 myeloid=c('LST1','TYROBP','FCER1G','AIF1','CTSS','LILRB1','CTSD','LGALS3','S100A10'),
 macrophage_TAM=c('CD68','LST1','TYROBP','FCER1G','AIF1','C1QA','C1QB','C1QC','MS4A7','CTSS','CD163','MRC1','CSF1R','MARCO','VSIG4','LGALS3'),
 CAF=c('COL1A1','COL1A2','COL3A1','COL5A1','COL6A1','COL6A2','DCN','LUM','SPARC','FAP','PDGFRA','PDGFRB','ACTA2','TAGLN','POSTN','COL11A1'),
 EMT=c('VIM','CDH2','SNAI1','SNAI2','TWIST1','TWIST2','ZEB1','ZEB2','MMP2','MMP9','MMP14','ITGA5','ITGB1','TGFB1','TGFBR1','TGFBR2','SERPINE1','FN1','COL1A1','COL3A1'),
 lipid_metabolism=c('ACACA','ACACB','FASN','SCD','ELOVL6','DGAT1','DGAT2','PLIN2','PLIN3','FABP4','FABP5','CPT1A','ACOX1','CD36','LPL','LDLR','SREBF1','SREBF2','HMGCR','HMGCS1','FDFT1','SQLE','ABCA1','APOE','PPARG','PPARA','CYP27A1','LIPE','PNPLA2'),
 inflammation=c('NLRP3','CASP1','GSDMD','IL1B','IL18','TNF','IL6','CXCL8','CCL2','CCL20','NFKB1','RELA','TLR4','TGFB1','CXCL1','CXCL2','CXCL5','CXCL10','CXCL11','PTGS2','S100A8','S100A9','NFKBIA','TNFAIP3'),
 pyroptosis_extended=c('TXNIP','NLRP3','PYCARD','CASP1','CASP4','CASP5','GSDMD','GSDME','IL1B','IL18','AIM2','NLRC4','NLRP1','GBP1','GBP5'))
core <- c('TXNIP','NLRP3','CASP1','GSDMD','IL1B','IL18')
sig$inflammation_noncore <- setdiff(sig$inflammation, core)
se <- readRDS(infile); if (!inherits(se,'SummarizedExperiment')) stop('TCGA input is not a SummarizedExperiment')
expr0 <- assay(se,'tpm_unstrand'); rd <- as.data.frame(rowData(se)); gene <- toupper(as.character(rd$gene_name)); gene[is.na(gene)|gene==''] <- rownames(expr0)[is.na(gene)|gene=='']; gene <- sub('\\..*$','',gene); keep_gene <- !duplicated(gene); expr <- expr0[keep_gene,,drop=FALSE]; rownames(expr) <- gene[keep_gene]; expr <- log2(expr+1)
cd <- as.data.frame(colData(se)); tumor <- cd$sample_type=='Primary Tumor' | cd$shortLetterCode=='TP'; tumor[is.na(tumor)] <- FALSE; expr <- expr[,tumor,drop=FALSE]; cd <- cd[colnames(expr),,drop=FALSE]; if (ncol(expr)<50) stop('Too few TCGA-PAAD primary tumor samples')
present <- tibble(signature=names(sig), n_genes=vapply(sig,function(g)sum(g%in%rownames(expr)),integer(1)), genes_present=vapply(sig,function(g)paste(intersect(g,rownames(expr)),collapse=';'),character(1))); write_csv(present,file.path(outdir,'signature_coverage.csv'))
scores <- as.data.frame(setNames(lapply(sig,function(g)zmean(expr,g)),names(sig))); scores$PSPS_core <- zmean(expr,core); scores$sample_id <- colnames(expr); scores$patient <- as.character(cd$patient); scores$sample_type <- as.character(cd$sample_type); write_csv(scores,file.path(outdir,'sample_scores.csv'))
cor_tbl <- bind_rows(lapply(setdiff(c('PSPS_core',names(sig)),'PSPS_core'),function(nm){z<-safe_cor(scores$PSPS_core,scores[[nm]]); tibble(score=nm,rho=z[['rho']],p_value=z[['p']],n=z[['n']])})) %>% mutate(fdr=p.adjust(p_value,'BH')); write_csv(cor_tbl,file.path(outdir,'psps_correlations.csv'))
core_expr <- as.data.frame(t(expr[intersect(core,rownames(expr)),,drop=FALSE])); core_expr$sample_id <- colnames(expr); write_csv(core_expr,file.path(outdir,'core_gene_log2tpm.csv'))
vital <- tolower(as.character(cd$vital_status)); dead <- vital %in% c('dead','deceased','1'); days_death <- suppressWarnings(as.numeric(cd$days_to_death)); days_fu <- suppressWarnings(as.numeric(cd$days_to_last_follow_up)); time <- ifelse(dead & is.finite(days_death)&days_death>0,days_death,days_fu); time[!is.finite(time)|time<=0] <- NA_real_
surv_dat <- tibble(sample_id=colnames(expr),patient=as.character(cd$patient),PSPS_core=scores$PSPS_core,time_days=time,event=as.integer(dead),age_years=suppressWarnings(as.numeric(cd$age_at_diagnosis))/365.25,stage=as.character(cd$ajcc_pathologic_stage),purity=suppressWarnings(as.numeric(cd$paper_ABSOLUTE.Purity)),vital_status=as.character(cd$vital_status)) %>% filter(is.finite(time_days),time_days>0); write_csv(surv_dat,file.path(outdir,'survival_input.csv'))
cox1 <- coxph(Surv(time_days,event)~PSPS_core,data=surv_dat); write_csv(broom::tidy(cox1,conf.int=TRUE,exponentiate=TRUE),file.path(outdir,'cox_psps_univariable.csv'))
surv_dat <- surv_dat %>% mutate(PSPS_group=if_else(PSPS_core>=median(PSPS_core,na.rm=TRUE),'High','Low')); cox_group <- coxph(Surv(time_days,event)~PSPS_group,data=surv_dat); write_csv(broom::tidy(cox_group,conf.int=TRUE,exponentiate=TRUE),file.path(outdir,'cox_psps_median_group.csv')); fit <- survfit(Surv(time_days,event)~PSPS_group,data=surv_dat); km <- ggsurvplot(fit,data=surv_dat,risk.table=TRUE,pval=TRUE,conf.int=TRUE,palette=c('#2C7FB8','#D95F0E'),xlab='Days',ylab='Overall survival probability',title='TCGA-PAAD: PSPS_core and overall survival'); ggsave(file.path(figdir,'PSPS_OS_KM.pdf'),km$plot,width=7,height=5); pdf(file.path(figdir,'PSPS_OS_KM_risk_table.pdf'),width=7,height=2.6); print(km$table); dev.off()
stage_clean <- ifelse(grepl('^Stage I$|^Stage IA$|^Stage IB$',surv_dat$stage,ignore.case=TRUE),'I',ifelse(grepl('^Stage III',surv_dat$stage,ignore.case=TRUE),'III',ifelse(grepl('^Stage II',surv_dat$stage,ignore.case=TRUE),'II',ifelse(grepl('^Stage IV',surv_dat$stage,ignore.case=TRUE),'IV',NA)))); surv_dat$stage_group <- factor(stage_clean); surv_adj <- surv_dat %>% filter(is.finite(age_years),!is.na(stage_group)); if(nrow(surv_adj)>=50 && nlevels(droplevels(surv_adj$stage_group))>=2){cox_adj<-coxph(Surv(time_days,event)~PSPS_core+age_years+stage_group,data=surv_adj); write_csv(broom::tidy(cox_adj,conf.int=TRUE,exponentiate=TRUE),file.path(outdir,'cox_psps_adjusted_age_stage.csv'))}else writeLines('Adjusted Cox model not run: insufficient complete cases or stage variation.',file.path(outdir,'cox_psps_adjusted_age_stage.txt'))
surv_purity <- surv_dat %>% filter(is.finite(purity), is.finite(age_years), !is.na(stage_group)); if(nrow(surv_purity)>=50 && nlevels(droplevels(surv_purity$stage_group))>=2){cox_purity<-coxph(Surv(time_days,event)~PSPS_core+age_years+purity+stage_group,data=surv_purity); write_csv(broom::tidy(cox_purity,conf.int=TRUE,exponentiate=TRUE),file.path(outdir,'cox_psps_adjusted_age_stage_purity.csv'))}else writeLines('Purity-adjusted Cox model not run: insufficient complete cases or stage variation.',file.path(outdir,'cox_psps_adjusted_age_stage_purity.txt'))
for(nm in c('immune_infiltration','CAF','macrophage_TAM','EMT','lipid_metabolism','inflammation')){p<-ggplot(scores,aes(x=.data[[nm]],y=PSPS_core))+geom_point(size=1.7,alpha=.75,colour='#2C7FB8')+geom_smooth(method='lm',se=TRUE,colour='#D95F0E')+theme_classic(base_size=11)+labs(x=paste0(nm,' score'),y='PSPS_core',title=paste0('TCGA-PAAD: PSPS and ',nm)); ggsave(file.path(figdir,paste0('PSPS_vs_',nm,'.pdf')),p,width=5.5,height=4.3)}
summary_lines <- c('TCGA-PAAD external validation of the fat-pancreas–pyroptosis candidate axis',paste0('Input: ',basename(infile)),paste0('Primary tumor samples analyzed: ',ncol(expr)),paste0('Survival complete cases: ',nrow(surv_dat),'; deaths: ',sum(surv_dat$event)),'PSPS_core = mean of row-wise z-scored TXNIP, NLRP3, CASP1, GSDMD, IL1B, IL18.','Signature scores = mean of row-wise z-scored genes present in TCGA-PAAD TPM matrix.','This analysis tests clinical relevance of a candidate axis in pancreatic cancer; it does not establish fatty pancreas in TCGA-PAAD.','Bulk RNA-seq signatures reflect tumor composition and transcriptional programs; immune/CAF/TAM scores are marker-module proxies, not direct cell counts.','Use continuous Cox estimates and correlations as primary evidence; median group KM is descriptive and requires independent validation.'); writeLines(summary_lines,file.path(outdir,'analysis_manifest.txt')); writeLines(capture.output(sessionInfo()),file.path(outdir,'sessionInfo.txt')); cat(paste(summary_lines,collapse='\n'),'\n')
logrank <- survdiff(Surv(time_days,event)~PSPS_group,data=surv_dat); logrank_p <- 1-pchisq(logrank$chisq, df=length(logrank$n)-1)
survival_summary <- surv_dat %>% group_by(PSPS_group) %>% summarise(n=n(), deaths=sum(event), median_followup_days=median(time_days), median_PSPS=median(PSPS_core), .groups='drop'); survival_summary$logrank_p <- logrank_p; write_csv(survival_summary,file.path(outdir,'survival_group_summary.csv'))
